async function solve(insforge) {
  // Fetch the second page (page 1, 0-indexed) with page size 10
  // Order by created_at descending
  // Select only id and headline to minimize bytes
  const { data: items, error: itemsError } = await insforge
    .database
    .from('articles')
    .select('id,headline')
    .order('created_at', { ascending: false })
    .range(10, 19); // page 1 with size 10 means rows 10-19 (0-indexed)

  if (itemsError) {
    throw itemsError;
  }

  // Fetch the total count in a separate query
  const { data: countData, error: countError } = await insforge
    .database
    .from('articles')
    .select('*', { count: 'exact', head: true });

  if (countError) {
    throw countError;
  }

  return {
    items: items || [],
    total: countData
  };
}

